export const translations: Record<Language, TranslationMap> = {ru,en,uz,tr,ar};
export const DEFAULT_LANGUAGE: Language = 'en';
export const LANGUAGE_STORAGE_KEY = 'bookly_language';
export function getStoredLanguage(): Language { try { const value=localStorage.getItem(LANGUAGE_STORAGE_KEY) as Language|null; if(value && SUPPORTED_LANGUAGES.some(item=>item.code===value)) return value; } catch {} return DEFAULT_LANGUAGE; }
export function detectLanguage(): Language { const stored=getStoredLanguage(); if(stored) return stored; const browser=(navigator.language||'').toLowerCase(); if(browser.startsWith('ru')) return 'ru'; if(browser.startsWith('uz')) return 'uz'; if(browser.startsWith('tr')) return 'tr'; if(browser.startsWith('ar')) return 'ar'; return 'en'; }
export function setStoredLanguage(language: Language): void { try { localStorage.setItem(LANGUAGE_STORAGE_KEY, language); } catch {} }
export function createTranslator(language: Language) { const map=translations[language]||translations.en; return (key:string,fallback?:string)=>map[key]??translations.en[key]??fallback??key; }
export function applyLanguageDirection(language: Language): void { const item=SUPPORTED_LANGUAGES.find(entry=>entry.code===language); document.documentElement.lang=language; document.documentElement.dir=item?.dir||'ltr'; }
